public class InnerGatewayTargetCertificateConfigurationFactory(Action<Humidifier.BedrockAgentCore.GatewayTargetTypes.CertificateConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.GatewayTargetTypes.CertificateConfiguration>
{

    internal InnerGatewayTargetS3CertificateConfigurationFactory S3Factory { get; set; }

    internal InnerGatewayTargetSecretsManagerCertificateConfigurationFactory SecretsManagerFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayTargetTypes.CertificateConfiguration Create()
    {
        var certificateConfigurationResult = CreateCertificateConfiguration();
        factoryAction?.Invoke(certificateConfigurationResult);

        return certificateConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.GatewayTargetTypes.CertificateConfiguration CreateCertificateConfiguration()
    {
        var certificateConfigurationResult = new Humidifier.BedrockAgentCore.GatewayTargetTypes.CertificateConfiguration();

        return certificateConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayTargetTypes.CertificateConfiguration result)
    {
        base.CreateChildren(result);

        result.S3 ??= S3Factory?.Build();
        result.SecretsManager ??= SecretsManagerFactory?.Build();
    }

} // End Of Class

